    b+='<circle cx="40" cy="70" r="5"/><text x="30" y="95">point A</text>'
    b+='<line x1="120" y1="70" x2="260" y2="70" stroke="#333" stroke-width="3"/><circle cx="120" cy="70" r="5"/><circle cx="260" cy="70" r="5"/><text x="120" y="95">line segment AB</text>'
    b+='<line x1="30" y1="140" x2="280" y2="140" stroke="#2471a3" stroke-width="3"/><polygon points="20,140 34,133 34,147" fill="#2471a3"/><polygon points="290,140 276,133 276,147" fill="#2471a3"/><text x="90" y="165">line (no ends)</text>'
    b+='<line x1="340" y1="140" x2="520" y2="140" stroke="#c0392b" stroke-width="3"/><circle cx="340" cy="140" r="5" fill="#c0392b"/><polygon points="530,140 516,133 516,147" fill="#c0392b"/><text x="360" y="165">ray (one end)</text>'
