svgfile('c6-maths-line-ray-angle.svg',560,180,d())
chapter(6,'maths','lines-and-angles','Lines and Angles',
 ('Opening a book','Vidya opens the cover of her book a little. Then more. Then all the way back. The cover and the page make a corner that gets wider each time. That corner is an angle, and today we learn to name it, compare it and measure it.'),
 [('Point, segment, line and ray',['A point is an exact location. We draw it as a dot and name it with a capital letter.','Join two points by the shortest path and you get a line segment. It has two end points, so it has a fixed length.','If a segment is extended forever in both directions, we get a line. A line has no ends, so we can never draw the whole line.','Any two points fix exactly one line through them.','A ray starts at one point and goes on endlessly in one direction, like a torch beam. It has one starting point.']),
  ('What is an angle?',['An angle is formed by two rays that start at the same point.','The common starting point is the vertex and the two rays are the arms.','We name an angle by three letters with the vertex in the middle, such as angle DBE.','The size of an angle is the amount of turning from one arm to the other. It does not depend on how long we draw the arms.']),
  ('Comparing and special angles',['To compare two angles, place one over the other with the vertex and one arm together. The one that opens wider is greater.','A quarter turn makes a right angle. A half turn makes a straight angle, which looks like a straight line. A full turn makes a complete angle.','Angles smaller than a right angle are acute. Angles bigger than a right angle but smaller than a straight angle are obtuse.','An angle bigger than a straight angle but smaller than a complete turn is a reflex angle.']),
  ('Measuring angles',['We measure angles in degrees. A right angle is 90 degrees, a straight angle is 180 degrees and a complete turn is 360 degrees.','To measure with a protractor, put its centre on the vertex and line up one arm with the zero mark.','Read the scale where the other arm crosses it, starting from the zero that the first arm lies on.','To draw an angle of 70 degrees, draw one arm, place the protractor, mark 70 and join the mark to the vertex.'])],
 [('An angle measures 120 degrees. What type is it?',[('90 degrees is a right angle and 180 degrees is straight.','Compare with the two special values.'),('120 is between them, so it is obtuse.','More than 90 and less than 180.')]),
  ('How many right angles make a complete turn?',[('A complete turn is 360 degrees.','Full rotation.'),('360 divided by 90 is 4.','Four quarter turns.')])],
 ('Explain how you would measure the angle between the two arms of a pair of scissors.',['Identify the vertex and the two arms.','Put the protractor centre on the vertex.','Line one arm with zero and read the scale at the other arm.'],['Thinking a longer arm means a bigger angle.','Reading the wrong scale of the protractor.']),
 ['A point has position only. A segment has two ends. A line has none. A ray has one.','Two rays with one vertex make an angle, named with the vertex in the middle.','Angles are measured in degrees: right 90, straight 180, complete 360.','Acute is less than 90 and obtuse is between 90 and 180.'],
 [mcq('p2-1',1,'How many end points does a line segment have?','2',[('1','A ray has one starting point. A segment has two.'),('0','A line has none, but a segment is a piece with ends.')],'A segment is the shortest path between two points.'),
  mcq('p2-2',1,'Which has a starting point but no end?','A ray',[('A line segment','A segment has two ends.'),('A line','A line has no ends at all.')],'A ray begins at one point and goes on forever.'),
  mcq('p2-3',1,'How many degrees in a right angle?','90',[('180','180 is a straight angle.'),('45','45 is half of a right angle.')],'A right angle is a quarter turn: 90 degrees.'),
  mcq('p2-4',1,'In angle PQR, the vertex is','Q',[('P','P is a point on one arm.'),('R','R is a point on the other arm.')],'The vertex is always the middle letter.'),
  mcq('p2-5',2,'An angle of 135 degrees is','obtuse',[('acute','Acute means less than 90.'),('right','Right means exactly 90.')],'It lies between 90 and 180.'),
  num('p2-6',2,'How many degrees make a straight angle?',180,'A half turn is 180 degrees.',[(90,'That is a right angle.')]),
  tf('p2-7',2,'A longer drawing of the arms makes an angle bigger.',False,'An angle is about the turn between the arms, not their length.'),
  mcq('p2-8',2,'How many lines pass through two given points?','Exactly one',[('Two','Two points fix a single line.'),('Many','Many lines pass through one point, but only one through two.')],'Two points determine a unique line.'),
  num('p2-9',3,'A reflex angle is bigger than 180 and smaller than how many degrees?',360,'A full turn is 360 degrees.',[(180,'180 is where reflex begins.')]),
  mcq('p2-10',3,'The angle between the hour hand and minute hand at 3 o\'clock is','a right angle',[('a straight angle','That is 6 o\'clock.'),('an acute angle','The hands are a quarter turn apart.')],'3 o\'clock is a quarter turn, 90 degrees.')],
 svgs=[('c6-maths-line-ray-angle','Point, segment, line, ray and angle drawn side by side','The basic building blocks of geometry')],keep=['angle','vertex','ray','degree'])
